package mz.bam.seeky.android;
import android.content.*;import android.database.*;import android.database.sqlite.*;import java.io.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;import org.json.*;
public final class CourseCheck {
 static int checks;interface Work{void run()throws Exception;}
 static void ok(boolean v,String name){if(!v)throw new AssertionError(name);checks++;System.out.println("PASS "+name);}
 static void fails(Work w,String name)throws Exception{try{w.run();throw new AssertionError(name);}catch(IOException|IllegalArgumentException|IllegalStateException|SQLiteException|JSONException expected){ok(true,name);}}
 static Context context()throws Exception{return new Context(Files.createTempDirectory("seeky-course-").toFile());}
 static long version(Context c){SQLiteDatabase d=new SQLiteDatabase(c.getDatabasePath("seeky-studies.db"));try(Cursor cur=d.rawQuery("PRAGMA user_version",null)){cur.moveToFirst();return cur.getLong(0);}finally{d.close();}}
 static void legacy(Context c,int version)throws Exception{JSONObject schemas=new JSONObject(new String(Files.readAllBytes(Paths.get(System.getProperty("seeky.legacy_schema"))),"UTF-8"));SQLiteDatabase d=new SQLiteDatabase(c.getDatabasePath("seeky-studies.db"));for(Object sql:schemas.getJSONArray("v"+version))d.execSQL(sql.toString());d.execSQL("INSERT INTO subjects(id,title,color,created) VALUES(1,'Anterior',1,1)");d.execSQL("INSERT INTO notes(id,subject,title,body,created,updated) VALUES(1,1,'Nota anterior','Conteúdo anterior',1,1)");d.execSQL("PRAGMA user_version="+version);d.close();}
 static long course(StudyStore d,String title){return d.save("courses",0,StudyStore.values("title",title,"description","Descrição","created",1));}
 static long module(StudyStore d,long course,String title,String kind){return d.save("subjects",0,StudyStore.values("title",title,"color",1,"created",1,"course",course,"kind",kind));}
 static long material(Context c,StudyStore d,long group,String name)throws Exception{File f=new File(StudyFileProvider.directory(c),UUID.randomUUID()+".txt");Files.write(f.toPath(),("Material do curso · "+name).getBytes("UTF-8"));return d.save("materials",0,StudyStore.values("subject",group,"title",name,"name",name,"mime","text/plain","path",f.getPath(),"hash",StudyFiles.hash(f),"bytes",f.length(),"created",1,"updated",1));}
 static File backup(Context c,StudyStore d,String name)throws Exception{File f=new File(c.getCacheDir(),name);try(OutputStream out=new FileOutputStream(f)){StudyBackup.write(c,d,out);}return f;}
 static File rewrite(File source,JSONObject root,String name)throws Exception{File f=new File(source.getParentFile(),name);try(ZipFile zip=new ZipFile(source);ZipOutputStream out=new ZipOutputStream(new FileOutputStream(f))){Enumeration<? extends ZipEntry> entries=zip.entries();while(entries.hasMoreElements()){ZipEntry e=entries.nextElement();out.putNextEntry(new ZipEntry(e.getName()));if(e.getName().equals("study.json"))out.write(root.toString().getBytes("UTF-8"));else try(InputStream in=zip.getInputStream(e)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}out.closeEntry();}}return f;}
 static void migration()throws Exception{
  for(int v:new int[]{1,2}){Context c=context();legacy(c,v);try(StudyStore d=new StudyStore(c)){ok(d.get("subjects",1).n("course")==0&&d.get("subjects",1).s("kind").equals("subject"),"v"+v+" migration places existing subjects outside courses");ok(d.get("notes",1).s("body").equals("Conteúdo anterior"),"v"+v+" migration preserves existing notes");ok(d.count("courses",null,null)==0,"v"+v+" migration does not invent courses");}ok(version(c)==3,"v"+v+" migration commits study schema 3");}
  Context broken=context();legacy(broken,2);SQLiteDatabase raw=new SQLiteDatabase(broken.getDatabasePath("seeky-studies.db"));raw.execSQL("ALTER TABLE subjects ADD COLUMN kind TEXT DEFAULT 'subject'");raw.close();fails(()->new StudyStore(broken).getWritableDatabase(),"migration failure is reported");raw=new SQLiteDatabase(broken.getDatabasePath("seeky-studies.db"));boolean courseColumn=false;try(Cursor cols=raw.rawQuery("PRAGMA table_info(subjects)",null)){while(cols.moveToNext())courseColumn|=cols.getString(1).equals("course");}ok(!courseColumn,"failed migration rolls back earlier added course column");raw.close();ok(version(broken)==2,"failed migration retains old version");
 }
 static void hierarchy()throws Exception{Context c=context();try(StudyStore d=new StudyStore(c)){
  long rev=StudyState.revision(d),a=course(d,"Curso A"),b=course(d,"Curso B");ok(StudyState.revision(d)>rev,"course writes mark backup state dirty");long ma=module(d,a,"Módulo A","module"),mb=module(d,b,"Disciplina B","subject");long m=material(c,d,ma,"a.txt");material(c,d,mb,"b.txt");
  ok(d.rows("materials",StudyStore.scope(a,0),null,null,100).size()==1,"course scope excludes materials of other courses");ok(d.rows("materials",StudyStore.scope(a,mb),null,null,100).isEmpty(),"inconsistent subject/course scope cannot leak other course");ok(d.courses().get(0).n("module_count")==1&&d.courses().get(0).n("material_count")==1,"course cards count modules and materials without multiplying rows");
  d.save("subjects",ma,StudyStore.values("course",b));ok(d.get("materials",m).n("subject")==ma&&d.rows("materials",StudyStore.scope(b,0),null,null,100).size()==2,"moving module carries materials without copying their files");
  fails(()->module(d,999,"Invalid","module"),"module cannot refer to missing course");fails(()->module(d,a,"Invalid","unknown"),"unknown module kind is rejected");
  d.deleteCourse(b);ok(d.get("subjects",ma).n("course")==0&&d.get("subjects",mb).n("course")==0&&d.count("materials",null,null)==2,"course removal conserves modules and materials outside courses");
  d.deleteSubject(ma);ok(d.get("materials",m).n("subject")==0,"module removal conserves materials in General");
 }}
 static void backups()throws Exception{Context source=context();try(StudyStore s=new StudyStore(source)){
  long course=course(s,"Curso exportado"),module=module(s,course,"Módulo exportado","module"),material=material(source,s,module,"source.txt");
  long note=s.save("notes",0,StudyStore.values("subject",module,"material",material,"title","Nota","body","Texto","created",1,"updated",1));s.delete("notes",note);
  JSONObject paused=new JSONObject().put("group",module).put("at",0).put("queue",new JSONArray().put(new JSONObject().put("subject",""+module).put("material",""+material).put("prompt","Q").put("answer","A")));
  s.save("practice",0,StudyStore.values("payload",paused.toString(),"updated",1));
  source.getSharedPreferences("studies",0).edit().putLong("course",course).putLong("subject",module).apply();
  try(ReaderStore r=new ReaderStore(source)){r.bookmark(StudyFileProvider.uri(source,material).toString(),0,1,"Marca");}
  File archive=backup(source,s,"new.zip");JSONObject manifest=StudySnapshot.manifest(archive);ok(manifest.getString("format").equals("seeky-studies-2"),"new backup declares course-aware format 2");ok(manifest.getJSONObject("tables").getJSONArray("courses").length()==1,"new backup contains courses");
  Context target=context();try(StudyStore d=new StudyStore(target)){long existing=course(d,"Local"),local=module(d,existing,"Local module","subject");material(target,d,local,"local.txt");StudyBackup.restore(target,d,archive);StudyStore.Row imported=d.rows("courses","title=?",new String[]{"Curso exportado"},null,1).get(0),group=d.rows("subjects","title=?",new String[]{"Módulo exportado"},null,1).get(0);ok(imported.id()!=course&&group.n("course")==imported.id(),"merge import remaps colliding course IDs");ok(group.id()!=module&&d.rows("materials",StudyStore.scope(imported.id(),group.id()),null,null,10).size()==1,"merge import keeps material inside remapped module");
   long trash=d.rows("study_trash",null,null,null,1).get(0).id();d.restoreTrash(trash);ok(d.rows("notes",null,null,null,1).get(0).n("subject")==group.id(),"imported trash payload follows remapped module");ok(d.get("subjects",local).n("course")==existing,"merge import preserves existing course links");
   JSONObject resumed=new JSONObject(d.get("practice",1).s("payload"));ok(resumed.getLong("group")==group.id()&&resumed.getJSONArray("queue").getJSONObject(0).getLong("subject")==group.id(),"paused practice follows remapped module");
   long savedCount=d.count("courses",null,null);fails(()->StudyBackup.restore(target,d,archive),"existing paused practice prevents hiding another imported quiz");ok(d.count("courses",null,null)==savedCount,"practice conflict rolls back imported course hierarchy");
   StudyStore.Row item=d.rows("materials","subject=?",new String[]{""+group.id()},null,1).get(0);try(ReaderStore r=new ReaderStore(target)){ok(r.bookmarks(StudyFileProvider.uri(target,item.id()).toString()).size()==1,"import remaps reader bookmarks with material IDs");}
   long count=d.count("courses",null,null);JSONObject bad=new JSONObject(manifest.toString());bad.getJSONObject("tables").getJSONArray("subjects").getJSONObject(0).put("course",999);File invalid=rewrite(archive,bad,"invalid.zip");fails(()->StudyBackup.restore(target,d,invalid),"missing course relation aborts import");ok(d.count("courses",null,null)==count,"failed import rolls back courses added before invalid module");
  }
  JSONObject legacy=new JSONObject(manifest.toString());legacy.put("format","seeky-studies-1");legacy.getJSONObject("tables").remove("courses");JSONArray groups=legacy.getJSONObject("tables").getJSONArray("subjects");for(int n=0;n<groups.length();n++){groups.getJSONObject(n).remove("course");groups.getJSONObject(n).remove("kind");}File old=rewrite(archive,legacy,"old.zip");Context older=context();try(StudyStore d=new StudyStore(older)){StudyBackup.restore(older,d,old);ok(d.count("courses",null,null)==0&&d.rows("subjects",null,null,null,1).get(0).n("course")==0,"legacy backup imports without inventing courses");ok(d.count("materials",null,null)==1,"legacy backup retains material bytes and references");}
  Context exact=context();try(StudyStore d=new StudyStore(exact)){long retained=course(d,"Replaced");JSONObject malformed=new JSONObject(manifest.toString());malformed.getJSONObject("tables").getJSONArray("subjects").getJSONObject(0).put("course","999");File broken=rewrite(archive,malformed,"broken-exact.zip");fails(()->StudySnapshot.restore(exact,d,broken,StudyState.revision(d),"owner",1,"head"),"exact restore rejects module with absent course");ok(d.get("courses",retained).s("title").equals("Replaced"),"rejected exact restore keeps current courses");StudySnapshot.restore(exact,d,archive,StudyState.revision(d),"owner",1,"head");ok(d.count("courses",null,null)==1&&d.get("subjects",module).n("course")==course,"exact snapshot recovery retains original course/module identity");ok(exact.getSharedPreferences("studies",0).getLong("course",0)==course,"exact snapshot restores selected course preference");}
 }}
 static void paging()throws Exception{Context c=context();try(StudyStore d=new StudyStore(c)){long course=course(d,"Biblioteca"),group=module(d,course,"Módulo","module"),outside=module(d,0,"Outro","module");for(int n=0;n<27;n++)material(c,d,group,"Material "+n+".txt");material(c,d,outside,"Fora do curso.txt");String scope=StudyStore.scope(course,group);List<StudyStore.Row> first=d.page("materials",scope,null,"id DESC",12,0),second=d.page("materials",scope,null,"id DESC",12,12),last=d.page("materials",scope,null,"id DESC",12,24);ok(first.size()==12&&second.size()==12&&last.size()==3,"bounded bookshelf pages return twelve covers and the final remainder");Set<Long> ids=new HashSet<>();for(List<StudyStore.Row> page:Arrays.asList(first,second,last))for(StudyStore.Row item:page)ok(ids.add(item.id())&&item.n("subject")==group,"bookshelf pagination never duplicates or escapes the chosen module");ok(ids.size()==27,"pagination reaches every material in the selected module");ok(d.page("materials",scope+" AND title LIKE ?",new String[]{"%26%"},"id DESC",12,0).size()==1,"bookshelf pagination preserves search arguments");ok(d.page("materials",scope,null,"id DESC",12,99).isEmpty(),"a page past the end returns no invented items");}}
 static void readingProgress()throws Exception{Context c=context();try(StudyStore d=new StudyStore(c)){
 long id=material(c,d,0,"Leitura.txt");
 ok(StudyReading.advance(d,id,2,10)&&d.get("materials",id).n("progress")==20,"background reading advances the actual study material progress");
 ok(!StudyReading.advance(d,id,1,10)&&d.get("materials",id).n("progress")==20,"returning to an earlier page never reduces study progress");
 d.getWritableDatabase().beginTransaction();ok(StudyReading.advance(d,id,8,10)&&d.get("materials",id).n("progress")==80,"reading progress participates in an existing transaction");d.getWritableDatabase().endTransaction();
 ok(d.get("materials",id).n("progress")==20,"caller rollback restores the prior reading progress");
 ok(StudyReading.advance(d,id,10,10)&&d.get("materials",id).n("progress")==99,"reaching the end does not claim the material has been learned");
 d.save("materials",id,StudyStore.values("progress",100,"status","Concluído"));
 ok(!StudyReading.advance(d,id,2,10)&&d.get("materials",id).n("progress")==100,"manual completion survives later reading and listening");
 ok(!StudyReading.advance(d,999,2,10)&&!StudyReading.advance(d,id,1,0),"deleted materials and empty documents cannot create progress records");
 }}
 public static void main(String[] args)throws Exception{migration();hierarchy();backups();paging();readingProgress();System.out.println("PASS "+checks+" actual course, migration and backup checks over host SQLite JDBC");}
}
